func PauseRequest(store Store, p Principal, in PauseInput, now time.Time) (Request, error) {
	var req Request
	switch p.Type {
	case "Staff":
	default:
		return req, &Error{"principal", fmt.Sprintf("pause is not asked by a %s", p.Type)}
	}
	var err error
	rID := in.Resource
	var rUID EntityRef
	var rEntity Entity
	var rPointed []EntityRef
	var rStage *Stage
	rUID = EntityRef{"Ringi::Stage", rID}
	rStage, err = readStage(store, rID, "requester", "requesters", "approvers", "owner", "self_approval")
	if err != nil {
		return req, err
	}
	rEntity = entityStage(rUID, rStage)
	rPointed = pointedStage(rStage)
	var pUID EntityRef
	var pEntity Entity
	var pPointed []EntityRef
	var pStaff *Staff
	switch p.Type {
	case "Staff":
		pUID = EntityRef{"Ringi::Staff", p.ID}
		pStaff, err = readStaff(store, p.ID, "department", "suspended")
		if err != nil {
			return req, err
		}
		pEntity = entityStaff(pUID, pStaff)
		pPointed = pointedStaff(pStaff)
	}
	ctx := map[string]any{}
	return request("pause", pEntity, rEntity, append(pPointed, rPointed...), ctx), nil
}

