// Authorize asks Cedar (cedar-go, in this process) whether the action named action is allowed,
// through the action's own function (AuthorizeSubmit for submit). action is the action's name in
// Cedar, and resources holds the id of a resource by the name of its type in Cedar; the ids of
// types the action does not take are left alone. A name the gate has no action of (the kind
// action), an action that takes inputs of its own (input: ask it through its own function), and no
// id, or ids of two types, of the action's resource (resource) are a deny, with an *Error.
func Authorize(store Store, p Principal, action string, resources map[string]string, now time.Time) Answer {
	switch action {
	case "submit":
		id, ok := resources["Ticket"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of submit (Ticket)"}}
		}
		return AuthorizeSubmit(store, p, SubmitInput{Resource: id}, now)
	case "withdraw":
		id, ok := resources["Ticket"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of withdraw (Ticket)"}}
		}
		return AuthorizeWithdraw(store, p, WithdrawInput{Resource: id}, now)
	case "approve":
		id, ok := resources["Stage"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of approve (Stage)"}}
		}
		return AuthorizeApprove(store, p, ApproveInput{Resource: id}, now)
	case "send_back":
		id, ok := resources["Stage"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of send_back (Stage)"}}
		}
		return AuthorizeSendBack(store, p, SendBackInput{Resource: id}, now)
	case "reject":
		id, ok := resources["Stage"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of reject (Stage)"}}
		}
		return AuthorizeReject(store, p, RejectInput{Resource: id}, now)
	case "pause":
		id, ok := resources["Stage"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of pause (Stage)"}}
		}
		return AuthorizePause(store, p, PauseInput{Resource: id}, now)
	case "add_approver":
		id, ok := resources["Stage"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of add_approver (Stage)"}}
		}
		return AuthorizeAddApprover(store, p, AddApproverInput{Resource: id}, now)
	case "hand_over":
		id, ok := resources["Stage"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of hand_over (Stage)"}}
		}
		return AuthorizeHandOver(store, p, HandOverInput{Resource: id}, now)
	case "retract":
		id, ok := resources["Stage"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of retract (Stage)"}}
		}
		return AuthorizeRetract(store, p, RetractInput{Resource: id}, now)
	case "comment":
		id, ok := resources["Stage"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of comment (Stage)"}}
		}
		return AuthorizeComment(store, p, CommentInput{Resource: id}, now)
	case "see":
		id, ok := resources["Ticket"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of see (Ticket)"}}
		}
		return AuthorizeSee(store, p, SeeInput{Resource: id}, now)
	case "change_request_type":
		id, ok := resources["RequestType"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of change_request_type (RequestType)"}}
		}
		return AuthorizeChangeRequestType(store, p, ChangeRequestTypeInput{Resource: id}, now)
	case "read_audit":
		id, ok := resources["RequestType"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of read_audit (RequestType)"}}
		}
		return AuthorizeReadAudit(store, p, ReadAuditInput{Resource: id}, now)
	case "import_organization":
		id, ok := resources["Organization"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of import_organization (Organization)"}}
		}
		return AuthorizeImportOrganization(store, p, ImportOrganizationInput{Resource: id}, now)
	case "read_organization_audit":
		id, ok := resources["Organization"]
		if !ok {
			return Answer{Policies: []string{}, Err: &Error{"resource", "resources holds no id of the resource of read_organization_audit (Organization)"}}
		}
		return AuthorizeReadOrganizationAudit(store, p, ReadOrganizationAuditInput{Resource: id}, now)
	}
	return Answer{Policies: []string{}, Err: &Error{"action", fmt.Sprintf("the gate has no action %q", action)}}
}

// policies are the policies in Cedar's JSON keyed by their @id: read as one text, cedar-go names
// them policy0, policy1, …, and the policies that decide would not be named as the gate names
// them.
var policies = func() *cedar.PolicySet {
	var ps cedar.PolicySet
	if err := json.Unmarshal([]byte(policiesJSON), &ps); err != nil {
		panic(err)
	}
	return &ps
}()

