func cedarUID(r EntityRef) types.EntityUID {
	return types.NewEntityUID(types.EntityType(r.Type), types.String(r.ID))
}

func cedarValue(v any) types.Value {
	switch x := v.(type) {
	case bool:
		return types.Boolean(x)
	case int64:
		return types.Long(x)
	case EntityRef:
		return cedarUID(x)
	case string:
		return types.String(x)
	}
	return types.String(fmt.Sprint(v))
}

func cedarRecord(m map[string]any) types.Record {
	r := types.RecordMap{}
	for k, v := range m {
		r[types.String(k)] = cedarValue(v)
	}
	return types.NewRecord(r)
}

func ask(req Request) Answer {
	es := types.EntityMap{}
	for _, x := range req.Entities {
		parents := []types.EntityUID{}
		for _, p := range x.Parents {
			parents = append(parents, cedarUID(p))
		}
		es[cedarUID(x.UID)] = types.Entity{UID: cedarUID(x.UID), Attributes: cedarRecord(x.Attrs), Parents: types.NewEntityUIDSet(parents...)}
	}
	d, diag := cedar.Authorize(policies, es, cedar.Request{Principal: cedarUID(req.Principal), Action: cedarUID(req.Action), Resource: cedarUID(req.Resource), Context: cedarRecord(req.Context)})
	if len(diag.Errors) > 0 {
		return Answer{Policies: []string{}, Context: req.Context, Err: &Error{"cedar", fmt.Sprint(diag.Errors)}}
	}
	ps := []string{}
	for _, r := range diag.Reasons {
		ps = append(ps, string(r.PolicyID))
	}
	sort.Strings(ps)
	return Answer{Allowed: d == cedar.Allow, Policies: ps, Context: req.Context}
}
